head.script:
scwin.onpageload = function() {
    requires("uiplugin.popup");
};
scwin.onpageunload = function() {};
scwin.fn_openPopup = function(a) {
    console.log("aaaa = " + a)
    requires("uiplugin.popup");
    var options = {
        id: "popup2",
        type: "wframePopup", //browserPopup
        width: 900 + "px",
        height: 300 + "px",
        top: 100 + "px",
        left: 100 + "px",
        modal: true,
        useModalStack: true,
        onlyParam: true,
        style: "",
        resizable: true,
        status: false,
        menubar: false,
        scrollbars: false,
        title: false,
        useMaximize: true
    };
    $p.openPopup("wframePopup_table_inputCalendar_WESD-265_(WSQ-4442)_sub.xml", options);
};
scwin.trigger3_onclick = function(e) {
    scwin.fn_openPopup("bbb");
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#popup2_wframe_inputCal1_input').width() > 150", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
